# Batch 5 (2026-10-17): deep time, Africa/Asia/Oceania/Americas history, myths placed near events, UFO cases, hoaxes, stories proven true/false
H,M='history','myth'
def X(id,title,lane,status,pr,start,ev,main,alts,src,img=None,end=None,changed=None,dateNote=None):
  d=dict(id=id,title=title,lane=lane,status=status,priority=pr,start=start,end=end,ev=ev,main=main,alts=alts,src=src,img=img)
  if changed:d['changed']=changed
  if dateNote:d['dateNote']=dateNote
  return d
E=[
# --- part 1: deep time, early humans, ancient Africa
X('vredefort','Vredefort impact structure',H,'confirmed',2,-2023000000,['geological'],
 'The eroded remains of one of the largest impact structures on Earth, in the Free State, South Africa, dated to about 2.023 billion years ago (±4 million). The original crater is estimated at 170–300 km across; erosion of 7–11 km has removed it, leaving the Vredefort Dome (the rebounded central uplift). It is among the oldest accepted impact structures, after Yarrabubba. UNESCO World Heritage Site since 2005.',
 [('Impactor size','Older estimates put the asteroid at 10–15 km across; studies around 2022 suggest 20–25 km, which researchers say fits the shock features better.')],
 ['url:https://whc.unesco.org/en/list/1162|Vredefort Dome (UNESCO)|institution','wiki:Vredefort_impact_structure'],'Vredefort_impact_structure',
 changed='1937: Albritton and Boon propose an impact. 1961: Dietz and Hargraves find shatter cones, establishing the impact origin. 2005: UNESCO listing.'),
X('homo-naledi','Homo naledi and the disputed cave "burials"',H,'confirmed',2,-335000,['fossil','radiometric dating'],
 'A small-brained human species (brain 465–610 cm³, about 1.44 m tall) found in 2013 by cavers deep in the Rising Star Cave system, Cradle of Humankind, South Africa: more than 1,550 bone pieces from at least 15 individuals. In 2017 the remains were dated to 335,000–236,000 years ago, much younger than first expected for such a mosaic anatomy.',
 [('Deliberate burial (excavators)','Lee Berger, Paul Dirks and colleagues argue the bodies were deliberately carried or placed in the chamber, and in 2023 proposed burials and engraved signs; if true this would be the oldest known hominin burial.'),
  ('Natural deposition (critics)','Other researchers (e.g. Val 2016, Egeland et al. 2018, Foecke et al. 2025) argue the evidence is insufficient and that natural processes or non-burial deposition have not been ruled out; reviewers of the 2023 papers were largely critical.')],
 ['doi:10.7554/eLife.09560','doi:10.7554/eLife.24231','wiki:Homo_naledi'],'Homo_naledi',end=-236000,
 changed='2015: species named; age unknown, often assumed 1–2 million years. 2017: dated to 335,000–236,000 years. 2023–2025: burial claims published and contested.'),
X('madjedbebe','Madjedbebe: the oldest dated site in Australia?',H,'disputed',2,-65000,['archaeological','luminescence dating'],
 'A sandstone rock shelter in Arnhem Land, on Mirarr country, with more than 100,000 artefacts including ground stone axe heads, grinding stones and ground ochre. Occupation of at least 50,000 years has been widely accepted since the 1990s; excavations by Clarkson et al. (2012, 2015, published 2017) proposed about 65,000 ± 6,000 years.',
 [('Younger arrival','Some experts have questioned the 65,000-year estimate since its publication; the long-accepted minimum of about 50,000 years is not in dispute.')],
 ['doi:10.1038/nature22968','wiki:Madjedbebe'],'Arnhem_Land',
 dateNote='Proposed c. 65,000 ± 6,000 years ago; at least 50,000 years widely accepted',
 changed='1973: first test pit. 1989: thermoluminescence suggests c. 50,000 years. 2017: Clarkson et al. publish c. 65,000 years; debate continues.'),
X('lake-mungo','Mungo Lady and Mungo Man',H,'confirmed',2,-40000,['archaeological','radiometric dating'],
 'Human remains found by geomorphologist Jim Bowler at the dry Lake Mungo, Willandra Lakes, New South Wales: Mungo Lady (1968), one of the world\'s oldest known cremations, and Mungo Man (1974), laid on his back and sprinkled with red ochre, the earliest known example of such a burial. Mungo Man is dated to around 40,000 years ago and is the oldest Homo sapiens found in Australia. Mungo Lady was repatriated to Aboriginal custodians in 1992, and both were reburied in 2022.',
 [('Age debate','Estimates for Mungo Man have ranged from 28,000–32,000 years (1976) to 62,000 ± 6,000 years (Thorne et al. 1999); the commonly cited age today is around 40,000 years (Bowler et al. 2003).')],
 ['doi:10.1038/nature01383','url:https://whc.unesco.org/en/list/167|Willandra Lakes Region (UNESCO)|institution','wiki:Lake_Mungo_remains'],'Mungo_National_Park',
 dateNote='Around 40,000 years ago (estimates ranged 28,000–62,000)',
 changed='Before 1974 Aboriginal arrival in Australia was often put at c. 20,000 years ago; Mungo pushed it back to 40,000+ years.'),
X('nabta-playa','Nabta Playa stone circle',H,'disputed',2,-4800,['archaeological','archaeoastronomy'],
 'Neolithic site at a former seasonal lake in the Nubian Desert of southern Egypt, used by cattle herders. Malville, Wendorf and colleagues describe a ceremonial centre (c. 6100–5600 BCE), cattle burials, a small stone circle (c. 4800 BCE) roughly aligned with summer-solstice sunrise, and megalith lines possibly aligned with bright stars (4500–3600 BCE). It is often called one of the earliest archaeoastronomical sites; a UNESCO inventory rated its solar and stellar alignments as "hypothetical".',
 [('Older star-map claim (speculative)','Astrophysicist Thomas Brophy proposed that stones in the circle map Orion and that alignments date to c. 6270 BCE; the original excavators replied that these dates are about 1,500 years earlier than the megalithic phase.'),
  ('Sceptical view','Some researchers note the "calendar circle" gaps are too wide for precise calendrical use and that some "aligned" stones rest on dunes and may not be in original positions.')],
 ['doi:10.1038/33131','wiki:Nabta_Playa'],'Nabta_Playa',
 dateNote='Site used from c. 9th millennium BCE; stone circle c. 4800 BCE (Malville et al.)'),
X('kerma','Kingdom of Kerma (Nubia)',H,'confirmed',2,-2500,['archaeological','textual'],
 'Early Nubian civilisation centred at Kerma in Sudan, developing from about 2500 BCE and peaking c. 1750–1500 BCE, when it was a large urban kingdom rivalling Egypt. Remains include the huge mudbrick temple known as the Western Deffufa and royal tumuli with many human sacrifices. Egypt\'s New Kingdom absorbed it c. 1500 BCE; the later Kingdom of Kush may have grown out of it.',
 [('Changing interpretation','Excavator George Reisner (1920s) thought Kerma was an Egyptian governor\'s outpost; Charles Bonnet\'s later work showed it was an independent African kingdom, a view Egyptologists accepted only after about 20 years.')],
 ['wiki:Kerma_culture'],'Kerma_culture',end=-1500,
 changed='1920s: Reisner sees an Egyptian trading fort. Late 20th c.: Bonnet establishes Kerma as an indigenous kingdom.'),
X('punt','Land of Punt ("God\'s Land")',H,'confirmed',2,-2450,['textual','iconographic','isotopic','genetic'],
 'A trading partner known from Egyptian records from the 5th Dynasty (Sahure, 25th c. BCE) to the 20th Dynasty, supplying gold, incense, ebony, ivory and live animals. Hatshepsut\'s five-ship expedition is shown on her temple at Deir el-Bahri; ship remains at Mersa/Wadi Gawasis show the Red Sea port used. Egyptians sometimes called it Ta netjer, "God\'s Land". Its location is debated; most scholars place it in the Horn of Africa.',
 [('Location from baboons','Isotope studies of mummified baboons (2010, 2020) and ancient DNA (2023) point to Eritrea, Ethiopia and northwest Somalia; the 2023 DNA team suggested Adulis in Eritrea.'),
  ('Ancestral homeland idea','Early Egyptologists such as Petrie and Budge read "God\'s Land" as meaning Egyptians thought Punt was their ancestral homeland; later scholars connect the name with eastern (sunrise) lands and temple goods.'),
  ('Arabian location','Some identify Punt partly or wholly with the Arabian coast of the Red Sea.')],
 ['doi:10.7554/eLife.60860','wiki:Land_of_Punt'],'Land_of_Punt',end=-1150,
 dateNote='Expeditions recorded c. 25th–12th centuries BCE'),
X('queen-of-sheba','Queen of Sheba, Menelik and the Ark in Aksum',M,'myth-legend',2,-950,['textual','oral tradition'],
 'In the Hebrew Bible an unnamed queen of Sheba brings spices, gold and gems to King Solomon (1 Kings 10). The story grew in Jewish, Ethiopian Christian and Islamic traditions (Bilqis in Arabic, Makeda in Ge\'ez). Ethiopia\'s 14th-century Kebra Nagast makes her (as the daughter of the man who killed the serpent-king Arwe) the mother of Menelik I, ancestor of the Solomonic dynasty, who brings the Ark of the Covenant to Ethiopia. The Church of Our Lady Mary of Zion in Aksum says it holds the Ark. Historians locate Sheba (Saba) in Yemen; no trace of the queen herself has been found.',
 [('Ethiopian Orthodox tradition','The Ark (or the original tablets) is held in a chapel at Aksum, which only the guardian monk, appointed for life, may view; this is a matter of faith rather than a testable claim.'),
  ('Sceptical view','Edward Ullendorff said in 1992 that in 1941 he had seen the object, describing it as an empty medieval construction; the lack of access has led both Ethiopian and foreign scholars to doubt the claim.'),
  ('Trade-mission reading','Some scholars read the visit as a memory of South Arabian incense trade with Judah; a disputed reading of the Ophel inscription has been cited in support.')],
 ['wiki:Queen_of_Sheba','wiki:Kebra_Nagast','wiki:Church_of_Our_Lady_Mary_of_Zion'],'Queen_of_Sheba',
 dateNote='Story set in Solomon\'s reign (traditionally 10th c. BCE); Kebra Nagast written 14th c. CE'),
X('ife-heads','Ife heads and Frobenius\'s "African Atlantis"',H,'confirmed',2,1300,['archaeological'],
 'Naturalistic copper-alloy heads from Ife, the sacred and royal centre of the Yoruba (Nigeria), probably made in the 14th–15th centuries, likely representing kings (Ooni). Eighteen were found in 1938 at the Wunmonije Compound; one is in the British Museum. Their realism challenged dismissive Western views of African art.',
 [('Atlantis claim (debunked)','After finding an earlier Ife head, German ethnologist Leo Frobenius proposed they were made by an ancient Greek colony and that Yoruba culture preserved the lost civilisation of Atlantis (press headlines in 1911). Archaeology shows they are Yoruba works.'),
  ('Frobenius in context','Frobenius rejected the colonial idea that a "white" civilisation underlay African achievements, and W. E. B. Du Bois cited him; his Atlantis theory still assumed an outside origin.')],
 ['wiki:Ife_Head','wiki:Leo_Frobenius'],'Ife_Head',end=1500,
 changed='1910–1911: Frobenius links Ife to Atlantis. 1938: Wunmonije heads found; now recognised as Yoruba masterpieces of the 14th–15th c.'),
X('sundiata','Epic of Sundiata (founding of Mali)',M,'myth-legend',2,1235,['oral tradition','textual'],
 'Mande epic, kept by griots (jeliw) for centuries, about Sundiata Keita, founder of the Mali Empire (ruled c. 1235–1255). A prophecy foretells his birth; he cannot walk as a child, rises with a staff, goes into exile and returns to defeat the sorcerer-king Soumaoro Kanté of Sosso at the Battle of Kirina (c. 1235). Mansa Musa was his great-nephew. The best-known version, from griot Djeli Mamoudou Kouyaté, was published by D. T. Niane in 1960.',
 [('Historical core','Historians accept Sundiata as the real founder of Mali and Kirina (c. 1235) as a real battle; Ibn Battuta and Ibn Khaldun, who travelled to Mali in the following century, provide independent information. The magical episodes are epic tradition.'),
  ('Oral history','The epic is studied as an example of oral tradition carrying political history (and the Kouroukan Fouga "constitution") across many generations; versions differ in details.')],
 ['wiki:Epic_of_Sundiata','wiki:Sundiata_Keita'],'Mali_Empire',end=1255),
# --- part 2: Africa/Asia/Oceania
X('mali-atlantic-voyage','Mali\'s lost Atlantic fleet',H,'disputed',2,1311,['textual'],
 'In Cairo in 1324, Mansa Musa said that his predecessor sent 200 ships (plus 200 supply ships) to find the far edge of the Atlantic; one returned, reporting a "river" in the sea (probably the Canary Current). The ruler then sailed with 2,000 ships and never came back. The only account is al-Umari\'s record. The ruler is popularly called "Abu Bakr II", but that name comes from a 19th-century mistranslation; Ibn Khaldun names Musa\'s predecessor as Muhammad ibn Qu.',
 [('Reached the Americas (speculative)','Ivan van Sertima and Gaoussou Diawara proposed the fleet reached the New World, citing reports in Columbus-era sources.'),
  ('Mainstream view','Scholars note that no genuine African artefact has been found in a controlled excavation in the Americas and that there is no accepted evidence of pre-Columbian African contact.')],
 ['wiki:Abu_Bakr_II','wiki:Mansa_Musa'],'Canary_Current',
 dateNote='Before Musa\'s accession (c. 1312); story told in Cairo in 1324'),
X('jiahu-symbols','Jiahu symbols',H,'disputed',3,-6500,['archaeological'],
 'Signs incised on tortoise shells and bones at Jiahu, a Neolithic Peiligang-culture site in Henan, China (excavated 1989). Of 17 groups first identified, 11 are definite incised signs. A few resemble much later oracle-bone characters such as "eye" and "sun".',
 [('Earliest writing?','Some researchers see a very early writing system, partly because the tortoise shells hint at later Shang divination practice.'),
  ('Proto-writing / sign use','A 2003 Antiquity report interpreted them not as writing but as part of a long period of sign-use that eventually led to writing; most scholars doubt they are systematic writing.')],
 ['doi:10.1017/S0003598X00061329','wiki:Jiahu_symbols'],'Jiahu_symbols',
 dateNote='Seventh millennium BCE (often rounded to c. 6000 BCE)'),
X('oracle-bones','Oracle bones: "dragon bones" that proved the Shang',H,'confirmed',2,-1250,['archaeological','textual'],
 'Ox shoulder blades and turtle shells used for divination in the late Shang dynasty (c. 1250–1050 BCE): questions were carved, heat cracked the bone and the answer was read. About 13,000 bones with 130,000+ inscriptions are known. In the 19th century villagers near Anyang sold them as "dragon bones" for traditional medicine; in 1899 Wang Yirong recognised the marks as ancient Chinese writing. Excavations (1928–37) at Yinxu proved the Shang dynasty and its last capital were real.',
 [('Lost to medicine','Historian Xu Yahui notes no one knows how many inscribed bones were ground up by pharmacies before 1899.'),
  ('Malaria tale','The story that Wang noticed the writing on his own malaria medicine is described as a legend; how he actually obtained the bones is not known.')],
 ['wiki:Oracle_bone','wiki:Wang_Yirong'],'Oracle_bone',end=-1050,
 changed='Before 1899: Shang known only from later texts and sometimes doubted. 1899: inscriptions recognised. 1908: source traced to Anyang. 1928–37: excavations confirm the Shang capital.'),
X('plain-of-jars','Plain of Jars and the giants\' rice wine',H,'confirmed',2,-1240,['archaeological','luminescence dating','oral tradition'],
 'Thousands of large stone jars in clusters across the Xiangkhoang Plateau, Laos. Madeleine Colani (1930s) linked them to burial, and later excavations found cremated and secondary burials, beads and grave goods. Luminescence dating suggests jars were placed as early as 1240–660 BCE, while burials at Site 1 date to the 8th–13th centuries CE. The area was heavily bombed by the US Air Force during the Secret War in Laos (1960s), and only some sites have been cleared of unexploded bombs. UNESCO World Heritage Site.',
 [('Local legend','Lao legend tells of a race of giants whose king Khun Cheung defeated the enemy king Chao Angka and made the jars to brew and store rice wine (lau hai) for the victory feast.'),
  ('"Distilling vessel" idea','Some researchers suggested bodies were first placed in jars to decompose before cremation and secondary burial, as in later royal funeral customs of the region.')],
 ['doi:10.15184/aqy.2019.102','url:https://whc.unesco.org/en/list/1587|Megalithic Jar Sites in Xiengkhuang – Plain of Jars (UNESCO)|institution','wiki:Plain_of_Jars'],'Plain_of_Jars',
 dateNote='Jars placed c. 1240–660 BCE (OSL); Site 1 burials 8th–13th c. CE'),
X('genghis-tomb','The lost grave of Genghis Khan',H,'confirmed',2,1227,['textual','oral tradition'],
 'Genghis Khan died in August 1227; his grave has never been found. It is generally thought to be near the sacred mountain Burkhan Khaldun in the Khentii Mountains of Mongolia, and searches (recently with drones) face cultural objections because of the mountain\'s sanctity. The Genghis Khan Mausoleum in Inner Mongolia is a memorial, not his grave.',
 [('Legend: no witnesses','A frequently retold story says the funeral slaves were killed by guards who were themselves killed; this does not appear in contemporary sources.'),
  ('Legend: hidden by nature','Other tales say a river was diverted over the grave (echoing stories told of Gilgamesh and Alaric), horses trampled it flat, or trees were planted over it.'),
  ('Legend: the weeping camel','One tale says a baby camel was buried with the Khan so its mother could later lead the family back to the grave.')],
 ['wiki:Tomb_of_Genghis_Khan','wiki:Burkhan_Khaldun'],'Burkhan_Khaldun',
 dateNote='Death August 1227; location of grave unknown'),
X('xu-fu','Xu Fu\'s voyage for the elixir of life',H,'disputed',2,-219,['textual','oral tradition'],
 'Xu Fu, a court sorcerer of Qin Shi Huang, was sent twice (219–210 BCE) to find the elixir of immortality on the mythical Mount Penglai in the eastern sea, reportedly with thousands of young men and women. Sima Qian\'s Records of the Grand Historian says he reached a land of "flat plains and wide swamps", made himself king and never returned.',
 [('Legend in Japan','From a 10th-century account by the monk Yichu onward, Xu Fu is said to have landed in Japan; many Japanese shrines honour him as a bringer of farming, medicine and silk. Some writers even identified him with Emperor Jimmu (speculative).'),
  ('Mainstream view','The Japanese landing first appears in a text written more than 1,100 years after the voyage, and the accounts crediting him with new crops and techniques are also much later.')],
 ['wiki:Xu_Fu'],'Xu_Fu',end=-210),
X('tambora-1815','Tambora 1815: the lost kingdom and the year without a summer',H,'confirmed',1,1815,['eyewitness','geological','archaeological'],
 'The April 1815 eruption of Mount Tambora on Sumbawa, Indonesia (VEI 7) is the most powerful in recorded history. Pyroclastic flows destroyed the village and kingdom of Tambora; deaths from the eruption, famine and disease are estimated at roughly 71,000–100,000. The ash veil helped cause the "Year Without a Summer" in 1816, with harvest failures in many parts of the world. In 2004 excavations found a house and its inhabitants buried under ash, prompting the label "Pompeii of the East".',
 [('Lost language','The Tambora language, wiped out by the eruption, appears to have been an isolate, possibly the last survivor of the pre-Austronesian languages of central Indonesia.')],
 ['wiki:1815_eruption_of_Mount_Tambora','wiki:Tambora_culture','wiki:Year_Without_a_Summer'],'1815_eruption_of_Mount_Tambora'),
X('kuk-swamp','Kuk Swamp: farming invented in New Guinea',H,'confirmed',2,-7000,['archaeological','archaeobotanical'],
 'Wetland site in the Wahgi Valley highlands of Papua New Guinea with drainage ditches and planting features from about 9,000 years ago, used to grow taro, with bananas and sugar cane cultivated from about 6,900–6,400 years ago. UNESCO (2008) lists it as one of the few places where people independently invented agriculture.',
 [],['doi:10.1126/science.1085255','url:https://whc.unesco.org/en/list/887|Kuk Early Agricultural Site (UNESCO)|institution','wiki:Kuk_Swamp'],'Kuk_Swamp',
 dateNote='Earliest drainage c. 9,000 years ago (c. 7000 BCE)'),
X('kuwae','Kuwae: the island swallowed by an eruption',M,'disputed',2,1452,['oral tradition','geological','ice core'],
 'Oral traditions of Tongoa, Vanuatu, tell of a land called Kuwae destroyed by a great eruption; in the legend of Ti Tongoa Liseiriki a young man escapes along the coast to Tongariki. Thick 15th-century pyroclastic deposits blanket Tongoa and Epi, and a 6 × 12 km submarine caldera between them was found in 1994 and named Kuwae caldera.',
 [('Huge eruption linked to ice cores','Earlier studies linked Kuwae to a large sulphate spike in Antarctic ice dated 1452–1453 and estimated 30–60 km³ of magma; a 2012 study re-dated the spike to 1458, and tephra geochemistry does not match Kuwae, so the source remains unidentified.'),
  ('Smaller eruption','Another team argues the deposits indicate only a small to moderate eruption, possibly from a different caldera south of Tongoa, where the traditions actually place Kuwae.')],
 ['doi:10.1007/s00445-006-0075-4','wiki:Kuwae'],'Kuwae',
 dateNote='15th century CE; once dated 1452 from ice cores, now uncertain'),
X('haasts-eagle','Haast\'s eagle and the pouākai legend',H,'confirmed',2,1300,['fossil','genetic','oral tradition','rock art'],
 'The largest eagle known (10–18 kg), Hieraaetus moorei lived on New Zealand\'s South Island and hunted moa weighing up to 200 kg. Ancient DNA (2005) showed its closest relatives are small Hieraaetus eagles, implying very rapid growth in size. After Māori arrived (c. 1250–1275) the moa were hunted out, and the eagle died out about 1445. Māori rock art in South Canterbury appears to depict it.',
 [('Pouākai / Hōkioi legends','The eagle is commonly accepted as the pouākai of Māori tradition, a giant bird said to kill people as well as moa, which scientists consider physically plausible.'),
  ('Sceptical view','Some argue the hakawai and hōkioi stories refer instead to a snipe, and that pouākai may not refer to Haast\'s eagle since it is not known from the North Island.')],
 ['doi:10.1371/journal.pbio.0030009',"wiki:Haast's_eagle"],"Haast's_eagle",
 dateNote='Coexisted with Māori from c. 1250–1275 until extinction c. 1445'),
# --- part 3: Americas, African and South Asian myths, underwater claims
X('serpent-mound','Great Serpent Mound',H,'disputed',2,-300,['archaeological','radiocarbon'],
 'A 411 m (1,348 ft) long effigy mound in Adams County, Ohio, the largest serpent effigy known, with a triple-coiled tail and an open mouth around an oval feature. First surveyed by Squier and Davis (1848). It sits on the Serpent Mound crater, a 14 km impact structure formed 252–330 million years ago. Who built it, and when, is debated.',
 [('Adena builders, c. 300 BCE','Radiocarbon studies from 2014 onward (e.g. Romain et al. 2017), corroborated in 2019, place construction c. 300 BCE by Adena people, with repair or rebuilding c. 1100 CE.'),
  ('Fort Ancient builders, c. 1070 CE','Charcoal from a reopened trench (1996) gave c. 1070 CE; Brad Lepper argues the dated "organic sediment" from cores can read too old, and that serpent imagery and effigy mounds fit the Fort Ancient culture. Some suggest Halley\'s Comet (1066) inspired it (speculative).'),
  ('Religious / New Age readings','In 1901 Rev. Landon West claimed it marked the Garden of Eden; today New Age visitors and others see astronomical or spiritual meanings (belief rather than testable claim).')],
 ['doi:10.1080/01461109.2017.1371871','wiki:Serpent_Mound'],'Serpent_Mound',
 dateNote='c. 300 BCE (Adena) or c. 1070 CE (Fort Ancient), dates debated'),
X('mound-builders-myth','The "lost race" of the Mound Builders',M,'debunked',2,1833,['textual','archaeological'],
 'Indigenous peoples of eastern North America built earthen mounds for over 5,000 years, from Watson Brake (c. 3500 BCE) to Mississippian centres such as Cahokia. In the 19th century many Americans claimed instead that a vanished "lost race" built them: Israelites, Vikings, Welsh, people from Atlantis, or giants. Newspapers reported giant skeletons, and Josiah Priest\'s American Antiquities (1833) popularised the idea. Cyrus Thomas\'s 1894 Bureau of Ethnology report established that ancestors of Native Americans built the mounds.',
 [('Why it spread','Writers such as Robert Silverberg and Jason Colavito link the myth to racist views of Native Americans common at the time; Thomas Jefferson had already noted similarities between mound burials and Native practice.'),
  ('Hoaxes involved','Rafinesque\'s Walam Olum (1836) was later argued to be a hoax, and William Pidgeon\'s claims were exposed as fraudulent in 1886.'),
  ('Modern echoes','Versions linking mounds to Atlantis or Mu still circulate online (speculative).')],
 ['wiki:Mound_Builders','wiki:Cyrus_Thomas'],'Mound_Builders',end=1894,
 changed='1830s–1880s: "lost race" theories popular. 1886: Pidgeon\'s claims exposed. 1894: Cyrus Thomas report credits Native Americans.'),
X('amazon-cities','Lost cities of the Amazon: from Fawcett\'s "Z" to lidar',H,'confirmed',1,-500,['archaeological','lidar'],
 'Lidar surveys have mapped extensive pre-Columbian settlements in the Amazon rainforest: the Upano Valley sites in Ecuador (from c. 500 BCE, over a millennium earlier than other known complex Amazonian societies; about 6,000 platforms linked by roads, Science 2024) and the Casarabe culture of the Bolivian Llanos de Moxos (c. 500–1400 CE; platform mounds, pyramids up to 22 m, causeways and canals, Nature 2022).',
 [('Fawcett\'s "Z"','Explorer Percy Fawcett believed a lost city he called "Z" lay in the Mato Grosso and vanished searching for it in 1925; journalist David Grann reported (2005) that archaeologist Michael Heckenberger\'s work suggests a monumental culture, Kuhikugu, may have existed near where Fawcett was searching.')],
 ['doi:10.1126/science.adi6317','doi:10.1038/s41586-022-04780-4','wiki:Upano_Valley_sites','wiki:Casarabe_culture','wiki:Percy_Fawcett'],'Casarabe_culture',end=1400,
 changed='1914: Fawcett formulates "Z". 1925: he disappears. 2015: Ecuador funds Upano lidar. 2022: Casarabe lidar published. 2024: Upano Valley lidar published.'),
X('maya-collapse','Classic Maya collapse',H,'confirmed',2,750,['archaeological','paleoclimate','textual'],
 'In the 8th–9th centuries CE many southern lowland Maya cities, including Tikal, Copán, Palenque and Calakmul, stopped raising dated monuments and were abandoned. Maya civilisation continued in northern Yucatán (Chichén Itzá, Mayapán) and the highlands until the Spanish conquest (Nojpetén, 1697); millions of Maya live there today. More than 80 explanations have been proposed.',
 [('Drought','Lake sediments and cave records show severe drought; Evans et al. (2018) estimated annual rainfall fell 41–54%, up to 70% at peak. Drought is now the leading single explanation.'),
  ('Rupture, not collapse','Many scholars prefer "rupture" or transformation, pointing to warfare, political change (abandonment of the ajawlel system of kingship) and reduced trade as well as climate.')],
 ['doi:10.1126/science.aas9871','doi:10.1126/science.1080444','wiki:Classic_Maya_collapse'],'Tikal',end=950,
 dateNote='Decline mainly 8th–9th c. CE; northern cities flourished afterwards'),
X('cortes-quetzalcoatl','Omens of the conquest: was Cortés taken for Quetzalcoatl?',M,'disputed',2,1519,['textual'],
 'Nahua accounts written after the fall of Tenochtitlan (1521) describe eight omens before the Spanish arrived: a column of fire in the night sky (1517), temples burning, comets in threes, a lake boiling, a weeping woman, and a bird with a mirror in its crown. A famous later story says Moctezuma believed Cortés was the god Quetzalcoatl returning in the year Ce Acatl (1519).',
 [('Belief was real','Historian Hugh Thomas and others describe Moctezuma as weighing whether Cortés was a god or an envoy, and some scholars think some of the omens were real events later linked to the conquest.'),
  ('Post-conquest invention','Others note that Cortés never claimed in his letters to have been taken for a god, that the idea appears in European writings only in the 1540s, and that Spanish and friar-supervised sources had reasons to present the conquest as foretold.')],
 ['wiki:Spanish_conquest_of_the_Aztec_Empire','wiki:Moctezuma_II','wiki:Quetzalcoatl'],'Spanish_conquest_of_the_Aztec_Empire',
 dateNote='Omens said to begin c. 1509–1517; Spanish arrival 1519'),
X('tokoloshe','Tokoloshe',M,'myth-legend',3,1900,['oral tradition'],
 'In Nguni (Zulu, Xhosa and related) folklore of southern Africa the tokoloshe is a small, dwarf-like, mischievous or evil water spirit that can turn invisible by drinking water or swallowing a stone, and can be sent by a malevolent person to cause illness or death. A common protection is raising the bed on bricks; traditional healers (sangomas) or pastors may be called to banish it. It also features widely in South African satire and pop culture.',
 [('Proposed natural explanation','One explanation offered is that people sleeping on the floor around indoor fires in rondavels died of carbon-monoxide build-up near the ground, while those on raised beds survived, giving rise to the bed-on-bricks custom (interpretive, untested).')],
 ['wiki:Tokoloshe'],None,
 dateNote='Undated oral tradition; placed at c. 1900 for display only'),
X('mami-wata','Mami Wata, the African water spirit',M,'myth-legend',2,1450,['oral tradition','iconographic'],
 'Mami Wata ("Mother Water") is a mermaid-like water spirit or goddess of wealth, fertility, healing and beauty venerated across West, Central, East and Southern Africa and the Atlantic diaspora. Scholars trace her image to encounters with Europeans from the 15th century and European mermaid figures; from the mid-19th century a European print of the snake charmer Nala Damajanti reshaped her iconography, and Hindu imagery added a male consort, Papi Wata.',
 [('Diaspora relatives','Some scholars relate her to similar water spirits in the Caribbean and Latin America.'),
  ('Demonised','Some African Christian and Islamic communities regard her as a demon.')],
 ['wiki:Mami_Wata'],'Mami_Wata',
 dateNote='Iconography from 15th c. contact onward; snake-charmer image 19th c.'),
X('ram-setu','Rama Setu / Adam\'s Bridge',M,'myth-legend',2,-500,['textual','geological'],
 'A 48 km chain of limestone shoals between India and Sri Lanka. In the Ramayana (composed between the 8th c. BCE and 3rd c. CE) Rama\'s army builds a bridge to Lanka to rescue Sita; Islamic tradition says Adam crossed it after leaving Eden (name recorded c. 1030). Geologists say the strait was dry land during the last glacial period, flooded by around 7,000 years ago, and the shoals re-emerged as sea levels fell from about 5,000 years ago.',
 [('Built by humans?','A former Geological Survey of India director, a 2008 court submission and an episode of the Science Channel series What on Earth? claimed the structure is man-made; geologists describe the shoals as natural limestone formations.'),
  ('NASA images misread','During protests against the Sethusamudram canal project, NASA said its satellite photos had been misinterpreted: "remote sensing images ... cannot determine whether humans were involved."'),
  ('Location of Lanka','Many scholars place the epic\'s Lanka in central India rather than Sri Lanka.')],
 ["wiki:Adam's_Bridge",'wiki:Ramayana'],"Adam's_Bridge",
 dateNote='Ramayana composed c. 8th c. BCE–3rd c. CE; placed at 500 BCE'),
X('yonaguni','Yonaguni "underwater pyramid"',H,'debunked',2,1986,['geological','speculative'],
 'Stepped rock terraces off Yonaguni, Japan\'s southernmost island, found by a diver in 1986. Geologists including Robert Schoch, Wolf Wichmann, Patrick Nunn and Ogata et al. (2019) conclude they are natural Miocene sandstone (about 20 million years old) split along bedding planes and vertical joints, like similar terraces on shore. Japan\'s cultural agencies do not treat it as an archaeological site.',
 [('Man-made monument (speculative)','Marine geologist Masaaki Kimura argues it is a carved stepped monument with roads and a "stadium", first dating it to at least 10,000 years ago (possibly linked to Mu) and later (2007) to 2,000–3,000 years ago; Graham Hancock says so many odd features in one place is unlikely to be natural.'),
  ('Sceptical view','Critics note the steps are attached to bedrock, the "carvings" look like natural scratches, and strong currents explain the lack of loose blocks.')],
 ['wiki:Yonaguni_Monument'],'Yonaguni_Monument'),
# --- part 4: UFO cases, hoaxes, cryptids proven true
X('sunken-dwarka','Sunken Dwarka and the Gulf of Khambhat "city"',M,'disputed',2,-1500,['textual','archaeological','speculative'],
 'In the Mahabharata\'s Mausala Parva, Arjuna watches the sea flood and submerge Krishna\'s city of Dvaraka; the Harivamsa says it was built on land "released by the ocean". Underwater surveys off modern Dwarka and Bet Dwarka (1983–1990) found walls, a stone jetty and stone anchors; the Archaeological Survey of India interprets them as a port of the Middle kingdoms period destroyed probably by coastal erosion.',
 [('Dvaraka found','Marine archaeologist S. R. Rao concluded the remains show a city-state of c. 1500 BCE that is reasonably the Dvaraka of the epic (based on one carbon date).'),
  ('Gulf of Khambhat (disputed)','In 2001 India\'s science minister announced a submerged city in the Gulf of Khambhat older than the Indus civilisation; a dredged piece of wood dated to about 9,500 years. Archaeologists reject the dating because artefacts were dredged, not excavated, and some "tools" may be natural geofacts.')],
 ['wiki:Dvaraka','wiki:Dwarka','wiki:Marine_archaeology_in_the_Gulf_of_Khambhat'],'Dvaraka',
 dateNote='Rao\'s date c. 1500 BCE; epic dating uncertain'),
X('crystal-skulls','Crystal skulls',H,'debunked',2,1870,['scientific analysis'],
 'Quartz skulls sold as Aztec or Maya relics. None comes from a documented excavation. Studies at the British Museum (1967, 1996, 2004) and a British Museum–Smithsonian study (2008) found tool marks from rotary wheels and hard abrasives, showing 19th-century or later manufacture, probably in workshops at Idar-Oberstein, Germany. Many passed through the Paris dealer Eugène Boban (from 1870). The Mitchell-Hedges "Skull of Doom", said to have been found at Lubaantun, was bought at Sotheby\'s in 1943.',
 [('Mystical skulls (New Age)','Some New Age groups claim the skulls have paranormal powers; legends of magical crystal skulls do not appear in genuine Mesoamerican traditions.')],
 ['doi:10.1016/j.jas.2008.05.007','wiki:Crystal_skull'],'Crystal_skull',
 changed='1880s–1930s: skulls displayed as pre-Columbian. 1967–2008: museum studies show modern tool marks.'),
X('maya-2012','The 2012 "Maya apocalypse"',M,'debunked',2,2012,['textual','speculative'],
 '21 December 2012 ended a b\'ak\'tun, a 5,126-year cycle in the Mesoamerican Long Count calendar. Claims spread that the date would bring the end of the world (a collision with "Nibiru", a galactic alignment, solar storms) or a spiritual transformation. Maya scholars said no Classic Maya text predicts doom, and astronomers called the scenarios pseudoscience. The date passed with festivities at Chichén Itzá and Tikal.',
 [('Spiritual-transformation reading','New Age writers saw the date as the start of a new era of consciousness (belief rather than testable claim).')],
 ['wiki:2012_phenomenon','wiki:Mesoamerican_Long_Count_calendar'],'2012_phenomenon'),
X('nazca-mummies','"Alien" Nazca mummies at Mexico\'s Congress',H,'debunked',2,2017,['forensic analysis'],
 'In 2017 small three-fingered "mummies" said to come from near the Nazca Lines in Peru were promoted online, and Mexican journalist Jaime Maussan presented two to a Mexican Congress hearing on UFOs on 12 September 2023, claiming a third of their DNA was of "unknown origin". UNAM said it had made no such finding. Peru\'s prosecutor\'s office (2017) and forensic archaeologist Flavio Estrada concluded they are recently made dolls of human and animal bones joined with synthetic glue and paper.',
 [('Non-human beings (claim)','Maussan and doctors at a second hearing (November 2023) said the bodies were once living organisms and "potential evidence of non-human life forms", while declining to certify them as extraterrestrial.')],
 ['wiki:Jaime_Maussan'],'Jaime_Maussan',end=2023,
 changed='2017: first videos; Peru prosecutor finds dolls. 2023: shown at Mexican Congress; experts reaffirm hoax.'),
X('utsuro-bune','Utsuro-bune: the "hollow ship" of 1803',M,'myth-legend',2,1803,['textual','folklore'],
 'Four Japanese texts (1815–1844) say that on 22 February 1803 fishermen in Hitachi Province found a round vessel like an incense burner, with windows and strange writing inside, carrying a pale young woman with red hair who spoke an unknown language and clutched a box; they set her adrift again. Folklorists such as Yanagita Kunio see it as part of a long Japanese tradition of drifting-boat tales (e.g. Princess Wake, Konjiki-hime).',
 [('UFO encounter (speculative)','Some ufologists cite the story as an early close encounter with an extraterrestrial craft.'),
  ('Foreign castaway','In 1844 writer Kyokutei Bakin suggested from a book on Russian customs that the woman may have been Russian; a villager in one version suggests an exiled foreign princess.')],
 ['wiki:Utsuro-bune'],'Utsuro-bune',
 dateNote='Event dated 22 Feb 1803 in texts written 1815–1844'),
X('varginha-1996','Varginha "ET" incident (Brazil, 1996)',H,'disputed',2,1996,['eyewitness','official inquiry'],
 'On 20 January 1996 three young women in Varginha, Minas Gerais, said they saw a large-headed creature with red eyes and three bumps on its head. Rumours followed of UFOs, alien captures by the army, a hospital examination, a police officer\'s death and unexplained zoo animal deaths, and the case drew huge media coverage. A 1997 Brazilian military inquiry concluded the women had seen a local man nicknamed "Mudinho", crouching and dirty after heavy rain, and that military movements were routine.',
 [('Captured alien (claim)','Ufologists allege that one or more extraterrestrials were captured and moved by the military and that officials covered it up.'),
  ('Sceptical view','Sceptic Brian Dunning calls it a case where "literally nothing at all happened that was remotely unusual", with rumours linked together afterwards.')],
 ['wiki:Varginha_UFO_incident'],'Varginha_UFO_incident'),
X('kaikoura-1978','Kaikōura lights (New Zealand, 1978)',H,'disputed',2,1978,['eyewitness','radar','film'],
 'On 21 December 1978 Safe Air cargo pilots saw strange lights near the Kaikōura ranges, also tracked by Wellington radar. On 30–31 December an Australian TV crew aboard another flight filmed bright lights, including a large orb that seemed to pace the aircraft; the footage was shown worldwide.',
 [('Unexplained (Maccabee)','US optical physicist Bruce Maccabee calculated the object was very bright and 20 m or more across, and concluded it was an unknown phenomenon.'),
  ('Squid boats and optics','New Zealand\'s DSIR said the lights were most likely squid-fishing boats\' lamps, with atmospheric bending of radar and light, and distortion from filming through the window; astronomers suggested Jupiter or Mars (which would not show on radar), ball lightning or meteors, and Patrick Moore reflections, a balloon or an aircraft.')],
 ["wiki:Kaikōura_lights"],"Kaikōura_lights"),
X('okapi','Okapi: the "African unicorn" confirmed',H,'confirmed',2,1901,['biological'],
 'Europeans heard reports of an unknown forest animal, nicknamed the "African unicorn"; Henry Morton Stanley (1887) mentioned a donkey-like animal the local people called the atti. Harry Johnston, told about the animal by Congo forest people he had rescued from a showman, obtained striped skin and a skull, and the species was formally described in 1901 (first as Equus johnstoni, then Okapia johnstoni). It turned out to be a forest relative of the giraffe, found only in the northeast of the DR Congo.',
 [],['wiki:Okapi'],'Okapi',
 changed='1887: Stanley reports the atti. 1901: described by science from skin and skull.'),
X('giant-squid','The kraken and the giant squid',H,'confirmed',2,1857,['biological','textual'],
 'The kraken, a Norwegian sea monster big as an island, appears in a 1646 glossary and was described by Bishop Pontoppidan (1753). Giant squid tales are old among mariners, and zoologist Japetus Steenstrup named the giant squid Architeuthis in 1857; a French warship secured part of one in 1861. Its feeding tentacles can reach about 10 m. The first photos of a live giant squid in the wild were taken on 30 September 2004 by Tsunemi Kubodera and Kyoichi Mori; video followed in 2012.',
 [('Legend from squid?','Many think kraken stories (and perhaps the "sea monk" of c. 1550, the Caribbean Lusca or Greek Scylla) came from sightings of giant squid; claims of 20 m+ specimens remain undocumented.')],
 ['doi:10.1098/rspb.2005.3158','wiki:Giant_squid','wiki:Kraken'],'Kraken',
 changed='1753: kraken described as fact by Pontoppidan. 1857: Architeuthis named. 2004: first photos alive. 2012: first video.'),
]
